public interface ICustomerDao {                       // domain vocabulary
    Task<Customer?> FindAsync(long id, CancellationToken ct = default);
}
public sealed class SqlCustomerDao(IDbConnectionFactory db) : ICustomerDao {
    public async Task<Customer?> FindAsync(long id, CancellationToken ct) {
        await using var conn = await db.OpenAsync(ct);         // pooled by ADO.NET
        await using var cmd = conn.CreateCommand();
        cmd.CommandText = "SELECT Id, Name, Version FROM Customer WHERE Id = @id";
        cmd.Parameters.Add(new SqlParameter("@id", id));
        await using var reader = await cmd.ExecuteReaderAsync(ct);
        return await reader.ReadAsync(ct) ? Customer.From(reader) : null;  // stays inside
    }
}
